package io.elasticore.springboot3.entity;

import io.elasticore.springboot3.validation.InvariantViolationException;

import java.lang.reflect.Field;
import java.lang.reflect.Modifier;
import java.math.BigDecimal;
import java.util.Objects;

/**
 * The check behind a sealed aggregate's creation writer.
 *
 * A DDD root generated by ElastiCORE takes a request's values once, when it
 * is made. After it has been saved or loaded it is "settled", and from then
 * on its state changes only through its own methods. A request that sends a
 * settled root's value back unchanged - a PUT carrying the whole object - is
 * fine; one that tries to change it is refused with a 422.
 *
 * "Unchanged" is judged the way a person reading the request would judge it:
 * 10 and 10.00 are the same amount, and two value objects holding the same
 * parts are the same value even when they are different instances.
 */
public final class FixedAtCreation {

    private FixedAtCreation() {
    }

    /**
     * Refuses a write to a settled aggregate that would change a value.
     *
     * @param settled whether the aggregate has been saved or loaded
     * @param entity  the aggregate's name, for the message
     * @param field   the field being written
     * @param current what the aggregate holds now
     * @param value   what the request sent
     */
    public static void check(boolean settled, String entity, String field, Object current, Object value) {
        if (!settled || same(current, value)) return;
        throw new InvariantViolationException(String.format(
                "%s.%s is set when the %s is created; after that it changes only through %s's own methods",
                entity, field, entity, entity));
    }

    /** Refuses replacing a settled aggregate's members from outside. */
    public static void checkMembers(boolean settled, String entity, String field) {
        if (!settled) return;
        throw new InvariantViolationException(String.format(
                "%s.%s is set when the %s is created; after that it changes only through %s's own methods",
                entity, field, entity, entity));
    }

    /** Whether two values are the same value. */
    public static boolean same(Object a, Object b) {
        if (a == b) return true;
        if (a == null || b == null) return false;
        if (a instanceof BigDecimal && b instanceof BigDecimal) {
            return ((BigDecimal) a).compareTo((BigDecimal) b) == 0;
        }
        if (a.equals(b)) return true;
        // A value object without equals of its own: the same parts, the same value.
        // Known by its annotation, or - with the mapping in orm.xml, where the
        // class carries none - by being a class of its own that never said
        // what makes two of it equal.
        if (a.getClass() == b.getClass() && (isEmbeddable(a.getClass()) || valueWithoutEquals(a.getClass()))) {
            return sameParts(a, b);
        }
        return false;
    }

    private static boolean isEmbeddable(Class<?> type) {
        for (java.lang.annotation.Annotation an : type.getAnnotations()) {
            String name = an.annotationType().getName();
            if (name.equals("jakarta.persistence.Embeddable") || name.equals("javax.persistence.Embeddable")) {
                return true;
            }
        }
        return false;
    }

    private static boolean valueWithoutEquals(Class<?> type) {
        if (type.getName().startsWith("java.") || type.isEnum() || type.isArray()) return false;
        // An entity is compared by identity, never by its parts.
        for (java.lang.annotation.Annotation an : type.getAnnotations()) {
            if (an.annotationType().getName().endsWith(".Entity")) return false;
        }
        try {
            return type.getMethod("equals", Object.class).getDeclaringClass() == Object.class;
        } catch (NoSuchMethodException e) {
            return false;
        }
    }

    private static boolean sameParts(Object a, Object b) {
        for (Class<?> t = a.getClass(); t != null && t != Object.class; t = t.getSuperclass()) {
            for (Field f : t.getDeclaredFields()) {
                if (Modifier.isStatic(f.getModifiers()) || Modifier.isTransient(f.getModifiers())) continue;
                try {
                    f.setAccessible(true);
                    if (!same(f.get(a), f.get(b))) return false;
                } catch (ReflectiveOperationException | RuntimeException e) {
                    return Objects.equals(a, b);
                }
            }
        }
        return true;
    }
}
